static float frand(void){return (float)rand()/(float)RAND_MAX;}
static float radius_of(const Snake *s){int l=s->len>300?300:s->len;return 9.0f+l*0.035f;}
static void burst(float x,float y,u32 c,int n,int sz){for(int i=0;i<n;i++){for(int k=0;k<NPART;k++){if(part[k].life<=0){part[k].x=x;part[k].y=y;float a=frand()*2*PI;float sp=1+frand()*4;part[k].vx=cosf(a)*sp;part[k].vy=sinf(a)*sp;part[k].life=20+rand()%30;part[k].col=c;part[k].size=sz;break;}}}}
static void add_pellet(float x,float y,int size,int type){for(int k=0;k<NPEL;k++){int i=(pelrot+k)%NPEL;if(!pel[i].active){pel[i].x=x;pel[i].y=y;pel[i].size=size;pel[i].type=type;pel[i].active=1;pel[i].col=palette[rand()%12];pel[i].vx=(frand()-0.5f)*0.2f;pel[i].vy=(frand()-0.5f)*0.2f;pelrot=(i+1)%NPEL;return;}}}
static void spawn_snake(int i){Snake *s=&sn[i];float x=400+frand()*(WORLD-800),y=400+frand()*(WORLD-800);s->ang=frand()*2*PI;s->tgt=s->ang;s->len=10+rand()%8;for(int j=0;j<s->len;j++){s->x[j]=x-cosf(s->ang)*SP*j;s->y[j]=y-sinf(s->ang)*SP*j;}s->alive=1;s->respawn=0;s->boost=0;s->grow=0;s->tick=0;s->shield=0;s->shield_t=0;s->inv_t=0;s->level=1;s->xp=0;if(i==0){s->score=0;s->kills=0;s->deaths=0;s->skin=skin_sel;s->col=palette[skin_sel];s->col2=palette[(skin_sel+4)%12];strcpy(s->name,player_name);}else{s->score=rand()%800;s->kills=0;s->deaths=0;s->skin=rand()%12;s->col=palette[s->skin];s->col2=palette[(s->skin+5)%12];strcpy(s->name,bot_names[(i-1)%13]);}}
static void kill_snake(int i,int killer){Snake *s=&sn[i];for(int j=0;j<s->len;j+=2)add_pellet(s->x[j]+(frand()-0.5f)*12,s->y[j]+(frand()-0.5f)*12,2,rand()%4);burst(s->x[0],s->y[0],s->col,30,3);if(i==0){shake=14;dead_t=0;s->deaths++;}else{total_kills++;if(killer==0){sn[0].kills++;sn[0].score+=150;sn[0].xp+=50;combo++;combo_t=180;burst(s->x[0],s->y[0],0x00FFD23F,20,2);}}s->alive=0;s->respawn=220+rand()%120;}
static void spawn_power(void){for(int i=0;i<NPOW;i++)if(!pw[i].active){pw[i].x=200+frand()*(WORLD-400);pw[i].y=200+frand()*(WORLD-400);pw[i].type=rand()%6;pw[i].active=1;pw[i].timer=900+rand()%900;pw[i].col=palette[rand()%12];return;}}
static void spawn_trap(void){for(int i=0;i<NTRAP;i++)if(!trap[i].active){trap[i].x=200+frand()*(WORLD-400);trap[i].y=200+frand()*(WORLD-400);trap[i].active=1;trap[i].r=18+rand()%20;return;}}
static void bot_think(int i){Snake *s=&sn[i];float hx=s->x[0],hy=s->y[0];s->tgt+=(frand()-0.5f)*0.22f;if(s->tick%12==0){float best=420*420;int bi=-1;for(int k=0;k<NPEL;k++){if(!pel[k].active)continue;float dx=pel[k].x-hx,dy=pel[k].y-hy,d=dx*dx+dy*dy;if(d<best){best=d;bi=k;}}if(bi>=0)s->tgt=atan2f(pel[bi].y-hy,pel[bi].x-hx);if(difficulty>=2){float bd=1e9;int bj=-1;for(int o=0;o<NSN;o++){if(o==i||!sn[o].alive)continue;float dx=sn[o].x[0]-hx,dy=sn[o].y-hy;float d=dx*dx+dy*dy;if(d<bd){bd=d;bj=o;}}if(bj>=0&&bd<300*300&&sn[bj].len<s->len)s->tgt=atan2f(sn[bj].y[0]-hy,sn[bj].x[0]-hx);}}if(hx<250||hx>WORLD-250||hy<250||hy>WORLD-250)s->tgt=atan2f(WORLD/2-hy,WORLD/2-hx);float px=hx+cosf(s->ang)*60,py=hy+sinf(s->ang)*60;float rs=radius_of(s);for(int o=0;o<NSN;o++){if(o==i||!sn[o].alive)continue;float lim=rs+radius_of(&sn[o])+28;lim*=lim;for(int j=0;j<sn[o].len;j+=4){float dx=sn[o].x[j]-px,dy=sn[o].y[j]-py;if(dx*dx+dy*dy<lim){s->tgt=s->ang+1.6f;return;}}}for(int t=0;t<NTRAP;t++){if(!trap[t].active)continue;float dx=trap[t].x-px,dy=trap[t].y-py;if(dx*dx+dy*dy<220*220){s->tgt=s->ang+1.2f;return;}}}
static void update_snake(int i){Snake *s=&sn[i];if(!s->alive){if(--s->respawn<=0)spawn_snake(i);return;}s->tick++;if(s->shield_t>0)s->shield_t--;if(s->inv_t>0)s->inv_t--;if(s->shield_t==0)s->shield=0;if(i==0){if(pad_mag>0.3f)s->tgt=atan2f(pad_ay,pad_ax);s->boost=pad_boost;}else{bot_think(i);s->boost=(s->len>30&&(s->tick/90)%5==0)?1:0;}float d=s->tgt-s->ang;while(d>PI)d-=2*PI;while(d<-PI)d+=2*PI;float turn=0.075f;if(i==0&&speed_sel==2)turn=0.11f;if(i==0&&speed_sel==0)turn=0.05f;if(d>turn)d=turn;if(d<-turn)d=-turn;s->ang+=d;float sp=3.0f;if(speed_sel==2)sp=3.6f;if(speed_sel==0)sp=2.6f;if(s->boost&&s->len>12){sp=5.6f;if(s->tick%10==0){s->len--;add_pellet(s->x[s->len],s->y[s->len],1,0);}}if(slowmo>0)sp*=0.5f;s->x[0]+=cosf(s->ang)*sp;s->y[0]+=sinf(s->ang)*sp;for(int j=1;j<s->len;j++){float dx=s->x[j-1]-s->x[j],dy=s->y[j-1]-s->y[j];float dd=sqrtf(dx*dx+dy*dy);if(dd>SP){float f=(dd-SP)/dd;s->x[j]+=dx*f;s->y[j]+=dy*f;}}if(s->x[0]<0||s->x[0]>WORLD||s->y[0]<0||s->y[0]>WORLD){if(s->shield||s->inv_t>0){if(s->x[0]<0)s->x[0]=0;if(s->x[0]>WORLD)s->x[0]=WORLD;if(s->y[0]<0)s->y[0]=0;if(s->y[0]>WORLD)s->y[0]=WORLD;s->tgt+=PI;}else{kill_snake(i,-1);return;}}float rs=radius_of(s),er=rs+14;for(int k=0;k<NPEL;k++){if(!pel[k].active)continue;float dx=pel[k].x-s->x[0],dy=pel[k].y-s->y[0];if(dx*dx+dy*dy<er*er){pel[k].active=0;s->grow+=pel[k].size;s->score+=pel[k].size*5+(int)combo*2;s->xp+=2;if(i==0){total_eaten++;burst(pel[k].x,pel[k].y,pel[k].col,4,2);if(combo_t>0)combo++;}}}for(int k=0;k<NPOW;k++){if(!pw[k].active)continue;float dx=pw[k].x-s->x[0],dy=pw[k].y-s->y[0];if(dx*dx+dy*dy<er*er){pw[k].active=0;if(pw[k].type==0){s->shield=1;s->shield_t=600;}else if(pw[k].type==1){s->inv_t=400;}else if(pw[k].type==2){s->grow+=20;s->score+=200;}else if(pw[k].type==3){slowmo=300;}else if(pw[k].type==4){s->len+=10;if(s->len>MAXSEG)s->len=MAXSEG;}else{s->score+=500;s->xp+=100;}burst(pw[k].x,pw[k].y,0x00FFFF00,20,3);}}for(int t=0;t<NTRAP;t++){if(!trap[t].active)continue;float dx=trap[t].x-s->x[0],dy=trap[t].y-s->y[0];if(dx*dx+dy*dy<trap[t].r*trap[t].r){if(!s->shield&&s->inv_t<=0){kill_snake(i,-1);return;}else{trap[t].active=0;}}}while(s->grow>=2&&s->len<MAXSEG){s->x[s->len]=s->x[s->len-1];s->y[s->len]=s->y[s->len-1];s->len++;s->grow-=2;}if(s->len>=MAXSEG)s->grow=0;if(s->xp>=100*s->level){s->xp=0;s->level++;s->score+=100*s->level;burst(s->x[0],s->y[0],0x00FFD23F,25,3);}for(int o=0;o<NSN;o++){if(o==i||!sn[o].alive)continue;float lim=(rs+radius_of(&sn[o]))*0.75f;lim*=lim;for(int j=0;j<sn[o].len;j+=2){float dx=sn[o].x[j]-s->x[0],dy=sn[o].y[j]-s->y[0];if(dx*dx+dy*dy<lim){if(s->shield||s->inv_t>0){}else{kill_snake(i,o);return;}}}}}
static void init_game(void){memset(pel,0,sizeof(pel));memset(part,0,sizeof(part));memset(pw,0,sizeof(pw));memset(trap,0,sizeof(trap));for(int k=0;k<NPEL;k++)add_pellet(frand()*WORLD,frand()*WORLD,1+(rand()%5==0),rand()%4);for(int i=0;i<NPOW;i++)spawn_power();for(int i=0;i<NTRAP;i++)spawn_trap();for(int i=0;i<NSTAR;i++){star[i].x=frand()*WORLD;star[i].y=frand()*WORLD;star[i].tw=1+rand()%4;star[i].ph=frand()*6;}for(int i=0;i<NSN;i++){sn[i].score=0;spawn_snake(i);}dead_t=0;time_play=0;combo=0;combo_t=0;slowmo=0;shake=0;total_games++;}
static void read_pad(void){padInfo info;padData d;pad_ax=pad_ay=pad_mag=0;pad_boost=pad_x=pad_start=pad_select=pad_up=pad_down=pad_left=pad_right=pad_tri=pad_sq=pad_l1=pad_r1=pad_l2=pad_r2=pad_circle=0;ioPadGetInfo(&info);if(info.status[0]){ioPadGetData(0,&d);float ax=((int)d.ANA_L_H-128)/128.0f,ay=((int)d.ANA_L_V-128)/128.0f;if(d.BTN_LEFT)ax=-1;if(d.BTN_RIGHT)ax=1;if(d.BTN_UP)ay=-1;if(d.BTN_DOWN)ay=1;pad_ax=ax;pad_ay=ay;pad_mag=sqrtf(ax*ax+ay*ay);pad_boost=d.BTN_CROSS||d.BTN_R1||d.BTN_R2;pad_x=d.BTN_CROSS;pad_start=d.BTN_START;pad_select=d.BTN_SELECT;pad_up=d.BTN_UP;pad_down=d.BTN_DOWN;pad_left=d.BTN_LEFT;pad_right=d.BTN_RIGHT;pad_tri=d.BTN_TRIANGLE;pad_sq=d.BTN_SQUARE;pad_l1=d.BTN_L1;pad_r1=d.BTN_R1;pad_l2=d.BTN_L2;pad_r2=d.BTN_R2;pad_circle=d.BTN_CIRCLE;}}
static void update_game(void){frame++;if(combo_t>0)combo_t--;else combo=0;if(slowmo>0)slowmo--;if(shake>0)shake-=0.5f;if(beep_t>0)beep_t--;if(day_night)day_night++;for(int i=0;i<NSN;i++)update_snake(i);for(int k=0;k<NPART;k++){if(part[k].life>0){part[k].life--;part[k].x+=part[k].vx;part[k].y+=part[k].vy;part[k].vx*=0.98f;part[k].vy*=0.98f;}}int cnt=0;for(int k=0;k<NPEL;k++)cnt+=pel[k].active;for(int n=0;n<4&&cnt<NPEL-40;n++,cnt++)add_pellet(frand()*WORLD,frand()*WORLD,1+(rand()%5==0),rand()%4);for(int k=0;k<NPOW;k++){if(pw[k].active&&--pw[k].timer<=0)pw[k].active=0;if(!pw[k].active&&(rand()%600==0))spawn_power();}for(int t=0;t<NTRAP;t++){if(!trap[t].active&&(rand()%800==0))spawn_trap();}if(sn[0].alive){camx=sn[0].x[0];camy=sn[0].y[0];time_play+=1.0f/60.0f;if(sn[0].score>highscore)highscore=sn[0].score;if(sn[0].len>best_len)best_len=sn[0].len;if(sn[0].kills>=5)ach_kill5=1;if(sn[0].len>=100)ach_len100=1;if(sn[0].score>=5000)ach_score5000=1;if(total_eaten>=200)ach_eat200=1;}else{dead_t++;if(dead_t>60&&pad_x&&!x_prev){spawn_snake(0);sn[0].score=0;sn[0].kills=0;}}x_prev=pad_x;}
